from typing import List, Dict, Any
import csv
import io
import re
from collections import Counter

def parse_csv(raw_csv: str):
    text = raw_csv if raw_csv is not None else ""
    if not text.strip():
        return {"columns": [], "rows": []}

    lines = text.splitlines()
    nonempty = [ln for ln in lines if ln.strip()]
    if not nonempty:
        return {"columns": [], "rows": []}

    def split_candidates(line: str):
        cands = [", ", ",", "\t", ";", "|"]
        scores = []
        for d in cands:
            try:
                parts = next(csv.reader([line], delimiter=d, quotechar='"', skipinitialspace=False))
            except Exception:
                continue
            if len(parts) > 1:
                scores.append((len(parts), -len(d), d))
        scores.sort(reverse=True)
        return scores[0][2] if scores else None

    delimiter = split_candidates(nonempty[0]) or ","

    def parse_with(delim: str):
        try:
            return list(csv.reader(io.StringIO(text), delimiter=delim, quotechar='"', skipinitialspace=False))
        except Exception:
            return None

    rows = parse_with(delimiter)
    if rows is None and delimiter == ", ":
        rows = parse_with(",")
    if rows is None:
        rows = [re.split(r"\s*,\s*", ln) for ln in lines if ln.strip()]

    rows = [[cell if isinstance(cell, str) else str(cell) for cell in row] for row in rows]

    # Remove completely empty rows
    rows = [row for row in rows if any(cell.strip() != "" for cell in row)]
    if not rows:
        return {"columns": [], "rows": []}

    # Detect and skip preamble lines before a likely header/data table
    def row_score(row: List[str]) -> int:
        score = 0
        if len(row) >= 2:
            score += 2
        if any(re.search(r"\d", c) for c in row):
            score += 1
        if any(c.strip() == "" for c in row):
            score -= 1
        return score

    start = 0
    if len(rows) > 1:
        best_i = 0
        best_s = -10**9
        for i in range(min(len(rows), 10)):
            s = row_score(rows[i]) + (1 if len(rows[i]) >= len(rows[min(i + 1, len(rows) - 1)]) else 0)
            if s > best_s:
                best_s = s
                best_i = i
        start = best_i if best_i > 0 and best_s >= 2 else 0

    rows = rows[start:]

    # Normalize widths by padding/truncating to the most common width
    widths = [len(r) for r in rows if r]
    if widths:
        common = Counter(widths).most_common(1)[0][0]
    else:
        common = 0

    if common <= 0:
        return {"columns": [], "rows": []}

    norm_rows = []
    for r in rows:
        if len(r) < common:
            r = r + [""] * (common - len(r))
        elif len(r) > common:
            r = r[:common]
        norm_rows.append([str(c) for c in r])

    # If first row looks like a header, return columns/rows; otherwise synthesize columns
    first = norm_rows[0]
    header_like = False
    if len(norm_rows) >= 2:
        second = norm_rows[1]
        alpha_first = sum(bool(re.search(r"[A-Za-z]", c)) for c in first)
        alpha_second = sum(bool(re.search(r"[A-Za-z]", c)) for c in second)
        num_first = sum(bool(re.fullmatch(r"\s*[-+]?\d+(\.\d+)?\s*", c)) for c in first)
        num_second = sum(bool(re.fullmatch(r"\s*[-+]?\d+(\.\d+)?\s*", c)) for c in second)
        if alpha_first >= max(1, len(first) // 2) and num_first < num_second:
            header_like = True

    if header_like:
        columns = [c.strip() if c.strip() else f"column_{i+1}" for i, c in enumerate(first)]
        data_rows = norm_rows[1:]
        return {"columns": columns, "rows": data_rows}

    columns = [f"column_{i+1}" for i in range(common)]
    return {"columns": columns, "rows": norm_rows}
